package com.nvv.mediadata.data.model.tmdbimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializableconst val BaseURLTheMovieDatabaseRESTFULL = "https://api.themoviedb.org/3"const val BaseURLTheMovieDatabaseImage = "https://image.tmdb.org/t/p/"const val PosterTheMovieDatabase = "w300_and_h450_bestv2"const val BackgroundTheMovieDatabase = "w1920_and_h800_multi_faces"const val FaceTheMovieDatabase = "w138_and_h175_face"const val LogoTheMovieDatabase = "original"@Serializabledata class Image(	@SerialName("aspect_ratio") val aspectRatio: Double = 0.0,	@SerialName("height") val height: Int = 0,	@SerialName("iso_3166_1") val iso31661: String = "",	@SerialName("iso_639_1") val iso6391: String = "",	@SerialName("file_path") val filePath: String? = null,	@SerialName("vote_average") val voteAverage: Double = 0.0,	@SerialName("vote_count") val voteCount: Int = 0,	@SerialName("width") val width: Int)fun Image.getImage(path: String) : String {	return BaseURLTheMovieDatabaseImage + path + (this.filePath ?: "")}@Serializabledata class Images(	@SerialName("backdrops") val backdrops: List<Image> = emptyList(),	@SerialName("logos") val logos: List<Image> = emptyList(),	@SerialName("posters") val posters: List<Image> = emptyList())